ing:7px 9px}\n.card[data-size=\"6x6\"] .book{padding:10px 12px;gap:6px}\n.book.stale{border-left:3px solid var(--accent-alt)}\n.t1{display:flex;align-items:baseline;gap:6px;min-width:0}\n.ttl{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600}\n.pc{flex:none;font-variant-numeric:tabular-nums;font-weight:700;color:var(--accent)}\n.fin .pc{font-size:11px;font-weight:600;color:var(--muted)}\n.track{display:block;height:6px;border-radius:99px;background:var(--soft);overflow:hidden}\n.track i{display:block;height:100%;background:var(--accent);border-radius:99px}\n.t3{display:flex;justify-content:space-between;gap:6px;min-width:0;font-size:11px;color:var(--muted)}\n.t3 span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.pg{flex:none}\n.ago.warn{color:var(--accent-alt);font-weight:600}\n.empty{grid-column:1/-1;display:grid;justify-items:center;gap:8px;padding:14px 6px;text-align:center;color:var(--muted)}\n.cta{border:0;border-radius:999px;padding:6px 14px;background:var(--accent);color:var(--on-accent)!important;font-weight:600}\n.dbody{display:grid;gap:8px;min-width:0}\n.big{font-size:28px;font-weight:700;color:var(--accent);line-height:1.1}\n.kv{display:flex;justify-content:space-between;align-items:baseline;gap:8px;border-bottom:1px solid var(--line);padding:3px 0;min-width:0}\n.kv span{color:var(--muted);flex:none}\n.kv b{min-width:0;text-align:right;font-weight:600}\n";
function parseDay(s){
  if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s))return null;
  const p=s.split('-').map(Number);
  const t=new Date(p[0],p[1]-1,p[2]);
  return t.getFullYear()===p[0]&&t.getMonth()===p[1]-1&&t.getDate()===p[2]?t:null;
}
function daysAgo(s,today){
  const a=parseDay(s),b=parseDay(today);
  if(!a||!b)return null;
  return Math.round((b-a)/86400000);
}
function agoText(n){
  if(n==null)return '未记录日期';
  if(n<=0)return '今天';
  if(n===1)return '昨天';
  if(n<60)return n+'天前';
  if(n<365)return Math.floor(n/30)+'个月前';
  return Math.floor(n/365)+'年前';
}
function pctOf(b){
  const t=Number(b.total)||0;
  if(t<=0)return 0;
  if(b.finishedAt)return 100;
  return Math.max(0,Math.min(99,Math.floor((Number(b.page)||0)*100/t)));
}
function readFields(v,total0,today){
  let title=null,total=total0;
  if(v.title!==undefined){
    title=String(v.title||'').trim();
    if(!title)return {err:'请填写书名'};
  }
  if(v.total!==undefined){
    total=Number(v.total);
    if(v.total===''||!Number.isInteger(total)||total<1)return {err:'总页数需为不小于 1 的整数'};
  }
  const page=Number(v.page);
  if(v.page===''||v.page==null||!Number.isInteger(page)||page<0)return {err:'当前页码需为不小于 0 的整数'};
  if(page>total)return {err:'当前页码不能超过总页数（'+total+'）'};
  const lr=String(v.lastRead||'');
  if(lr){
    if(!parseDay(lr))return {err:'阅读日期格式不正确'};
    if(lr>today)return {err:'阅读日期不能晚于今天'};
  }
  return {title:title,total:total,page:page,lastRead:lr||null};
}
function mergeBook(b,r,today){
  const nb=Object.assign({},b,{total:r.total,page:r.page,lastRead:r.lastRead});
  if(r.title!=null)nb.title=r.title;
  nb.finishedAt=r.page>=r.total?(r.lastRead||today):null;
  return nb;
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,editor,panel,uid,day}=ctx;
  const STALE=14;
  const today=day();
  const books=Array.isArray(state&&state.books)?state.books:[];
  const active=books.filter(b=>!b.finishedAt);
  const done=books.filter(b=>b.finishedAt);
