  const act=(fn,next)=>update(fn).then(()=>go(next),()=>go({notice:'保存失败，数据未改变，请重试'}));

  function sortedActive(){
    const arr=active.slice();
    const key=b=>{const d=ageOf(b);return d==null?1e9:d;};
    arr.sort(ui.sort==='recent'?(a,b)=>key(a)-key(b):(a,b)=>key(b)-key(a));
    return arr;
  }
  function bar(p){const i=el('i',{});i.style.width=p+'%';return el('span',{class:'track'},i);}
  function open(b){go({view:'detail',id:b.id,confirmDel:null});}

  function bookItem(b){
    const p=pctOf(b),d=ageOf(b),stale=d!=null&&d>=STALE;
    return el('button',{class:'book'+(stale?' stale':''),type:'button',onclick:()=>open(b)},
      el('span',{class:'t1'},el('b',{class:'ttl',title:b.title},b.title),el('span',{class:'pc'},p+'%')),
      bar(p),
      el('span',{class:'t3'},el('span',{class:'pg'},b.page+'/'+b.total+' 页'),
        el('span',{class:'ago'+(stale?' warn':'')},(stale?'久未读 · ':'')+agoText(d))));
  }
  function doneItem(b){
    return el('button',{class:'book fin',type:'button',onclick:()=>open(b)},
      el('span',{class:'t1'},el('b',{class:'ttl',title:b.title},b.title),el('span',{class:'pc'},'已读完')),
      el('span',{class:'t3'},el('span',{class:'pg'},b.total+' 页'),el('span',{class:'ago'},b.finishedAt+' 读完')));
  }
