    const pages=done.reduce((n,b)=>n+(Number(b.total)||0),0);
    const sum=[el('span',{class:'sumtxt'},hist?'已读完 '+done.length+' 本 · 共 '+pages+' 页':active.length+' 本在读 · '+staleN+' 本超过 '+STALE+' 天未读')];
    if(!hist&&active.length>1)sum.push(el('button',{class:'sort',type:'button',onclick:()=>go({sort:ui.sort==='recent'?'stale':'recent'})},ui.sort==='recent'?'最近读过在前':'最久未读在前'));
    const items=hist
      ?done.slice().sort((a,b)=>String(b.finishedAt).localeCompare(String(a.finishedAt))).map(doneItem)
      :sortedActive().map(bookItem);
