      items.push(el('div',{class:'empty'},...kids));
    }
    const kids=[
      el('div',{class:'head'},
        el('div',{class:'tabs',role:'tablist'},tab('active','在读',active.length),tab('history','历史',done.length)),
        el('button',{class:'add',type:'button','aria-label':'添加书籍',onclick:()=>go({view:'add',draft:addDraft()})},'＋',el('span',{class:'lbl'},' 添加'))),
      el('div',{class:'sum'},...sum)];
    if(ui.notice)kids.push(el('div',{class:'note',role:'status'},ui.notice));
    kids.push(el('div',{class:'list'},...items));
