  }


  function bookFields(){
    return [
      {key:'title',label:'书名',type:'text',required:true,placeholder:'例如：三体'},
      {key:'total',label:'总页数',type:'number',required:true,min:1,step:1},
      {key:'page',label:'当前页码（未开始填 0）',type:'number',required:true,min:0,step:1},
      {key:'lastRead',label:'最近阅读日期（可留空）',type:'date'}];
  }
  function addForm(){
    return editor({title:'添加书籍',draft:ui.draft,fields:bookFields(),submitLabel:'保存',
