          {view:'list',tab:fin?'history':'active',draft:null,notice:fin?'已读完，移入历史记录':null});
      }});
  }
  function editForm(b){
    return editor({title:'编辑书籍',draft:ui.draft,fields:bookFields(),submitLabel:'保存',
      onBack:()=>go({view:'detail'}),
      onSave:v=>{
        const r=readFields(v,null,today);
        if(r.err)return r.err;
        const fin=r.page>=r.total;
        return save(s=>patch(s,b.id,x=>mergeBook(x,r,today)),
          {view:fin?'list':'detail',tab:fin?'history':ui.tab,draft:null,notice:fin?'已读完，移入历史记录':null});
      }});
  }
  function updateForm(b){
    const fin=!!b.finishedAt;
    return editor({title:fin?'移回在读':'更新进度',draft:ui.draft,submitLabel:'保存',
      fields:[
        {key:'page',label:'当前页码（共 '+b.total+' 页）',type:'number',required:true,min:0,max:fin?b.total-1:b.total,step:1},
        {key:'lastRead',label:'最近阅读日期',type:'date',required:true}],
      onBack:()=>go({view:'detail'}),
      onSave:v=>{
        const r=readFields({page:v.page,lastRead:v.lastRead},b.total,today);
        if(r.err)return r.err;
        if(fin&&r.page>=b.total)return '移回在读需要页码小于总页数 '+b.total;
