    const rows=[el('div',{class:'big'},p+'%'),bar(p),row('页码',b.page+' / '+b.total+' 页')];
    rows.push(fin?row('读完于',b.finishedAt):row('还剩',(b.total-b.page)+' 页'));
    rows.push(row('最近阅读',b.lastRead?b.lastRead+'（'+agoText(d)+'）':'未记录'));
    if(ui.notice)rows.push(el('div',{class:'note',role:'status'},ui.notice));
    const del={label:ui.confirmDel===b.id?'再点一次确认删除':'删除',onClick:()=>{
      if(ui.confirmDel!==b.id){go({confirmDel:b.id});return;}
      act(s=>Object.assign({},s,{books:(s.books||[]).filter(x=>x.id!==b.id)}),{view:'list',id:null,confirmDel:null,notice:'已删除《'+b.title+'》'});
    }};
    const actions=fin
      ?[{label:'移回在读',primary:true,onClick:()=>go({view:'update',draft:{page:'',lastRead:today}})},del]
      :[{label:'更新进度',primary:true,onClick:()=>go({view:'update',draft:{page:String(b.page),lastRead:today}})},
        {label:'编辑',onClick:()=>go({view:'edit',draft:{title:b.title,total:String(b.total),page:String(b.page),lastRead:b.lastRead||''}})},
        {label:'读完了',onClick:()=>act(s=>patch(s,b.id,x=>Object.assign({},x,{page:x.total,lastRead:today,finishedAt:today})),{view:'list',tab:'history',id:null,notice:'已读完，移入历史记录'})},
        del];
    return panel({title:b.title,onBack:()=>go({view:'list',confirmDel:null}),body:el('div',{class:'dbody'},...rows),actions:actions});
  }

  function render(){
    const b=ui.id?books.find(x=>x.id===ui.id):null;
    const view=ui.view||'list';
    if(view==='add'&&ui.draft)return root.append(addForm());
    if(b&&ui.draft&&view==='edit'&&!b.finishedAt)return root.append(editForm(b));
    if(b&&ui.draft&&view==='update')return root.append(updateForm(b));
    if(b&&view==='detail')return root.append(detailView(b));
    root.append(listView());
  }
  render();
}

